#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<long long> sums;
    long long getSum(TreeNode* node) {
        if (!node) return 0;
        long long s = node->val + getSum(node->left) + getSum(node->right);
        sums.push_back(s);
        return s;
    }
    int maxProduct(TreeNode* root) {
        sums.clear();
        long long total = getSum(root);
        long long best = 0;
        for (long long s : sums) {
            best = std::max(best, s * (total - s));
        }
        return best % 1000000007;
    }
};

import java.util.*;

class Solution {
    private List<Long> sums = new ArrayList<>();
    private long getSum(TreeNode node) {
        if (node == null) return 0;
        long s = node.val + getSum(node.left) + getSum(node.right);
        sums.add(s);
        return s;
    }
    public int maxProduct(TreeNode root) {
        sums.clear();
        long total = getSum(root);
        long best = 0;
        for (long s : sums) {
            best = Math.max(best, s * (total - s));
        }
        return (int)(best % 1_000_000_007);
    }
}

var maxProduct = function(root) {
    const sums = [];
    const getSum = (node) => {
        if (!node) return 0n;
        const s = BigInt(node.val) + getSum(node.left) + getSum(node.right);
        sums.push(s);
        return s;
    };
    const total = getSum(root);
    let best = 0n;
    for (const s of sums) {
        const prod = s * (total - s);
        if (prod > best) best = prod;
    }
    return Number(best % 1000000007n);
};
